package com.fxrates.ui

/**
 * Every user-facing string of the app. The app is English-only, so a constant is enough; a
 * string is never written inline in a composable.
 */
object Strings {

    const val RATES_TITLE = "Rates"
    const val RATES_SEARCH_HINT = "Search by code or name"
    const val RATES_NOTHING_FOUND = "Nothing found"
    const val ERROR_TITLE = "Could not load the rates"
    const val RETRY = "Retry"
    const val REFRESH = "Refresh"
    const val BACK = "Back"
    const val DETAIL_EMPTY = "No rates available for this period"
    const val DETAIL_HISTORY = "Last 30 days"
    const val DETAIL_CHANGE = "Change over period"
    const val DETAIL_UNAVAILABLE = "Unavailable"

    fun detailTitle(base: String, code: String): String = "1 $base in $code"

    fun ratesSubtitle(base: String, date: String): String = "1 $base В· $date"

}
package com.fxrates.feature.rates.detail.mvi

import com.arkivanov.mvikotlin.extensions.coroutines.CoroutineExecutor
import com.fxrates.core.utils.resourceFlow
import com.fxrates.domain.repository.RatesRepository
import com.fxrates.feature.rates.detail.mvi.RatesDetailStore.Action
import com.fxrates.feature.rates.detail.mvi.RatesDetailStore.Intent
import com.fxrates.feature.rates.detail.mvi.RatesDetailStore.Label
import com.fxrates.feature.rates.detail.mvi.RatesDetailStore.Message
import com.fxrates.feature.rates.detail.mvi.RatesDetailStore.State
import kotlinx.coroutines.flow.launchIn
import kotlinx.coroutines.flow.onEach

internal class RatesDetailExecutor(
    private val repository: RatesRepository,
) : CoroutineExecutor<Intent, Action, State, Message, Label>() {

    override fun executeAction(action: Action) = when (action) {
        is Action.LoadHistory -> loadHistory(action)
    }

    override fun executeIntent(intent: Intent) = when (intent) {
        is Intent.OnRetry -> forward(Action.LoadHistory(base = state().base, code = state().code))
        is Intent.OnBack -> publish(Label.Back)
    }

    private fun loadHistory(action: Action.LoadHistory) {
        resourceFlow { repository.getRateHistory(base = action.base, code = action.code) }
            .onEach { history -> dispatch(Message.UpdateHistory(history)) }
            .launchIn(scope)
    }

}
